from pathlib import Path
root=Path(__file__).resolve().parent
head=''.join(f'<link rel="stylesheet" href="../../../node_modules/@fontsource/dm-sans/latin-{w}.css">' for w in (400,500,600,700))+'<link rel="stylesheet" href="../../../node_modules/@fontsource/dm-mono/latin-400.css">'+''.join(f'<link rel="stylesheet" href="../../../src/{f}.css">' for f in ('styles','product','cabinet'))
def face(value='meh',size='',arms=False):
 bodies={
 'meh':'M15 65C12 45 26 27 45 29c11 2 14-5 29-2 19 3 33 20 32 39-1 19-17 24-46 24S18 84 15 65Z',
 'favorite':'M20 60c2-14 10-20 14-30C40 14 54 12 64 18c12-5 24 4 28 18 4 10 13 17 12 30-1 19-20 25-43 25S17 81 20 60Z',
 'would_not_again':'M16 61c-1-19 13-36 31-37 14-1 22 6 33 7 18 3 25 20 23 36-2 19-19 24-43 23S17 82 16 61Z'}
 hands='M19 65q-10 7-13-3 M101 65q10 7 13-3' if value=='meh' else 'M22 60Q10 59 9 49 M99 58q10-3 11-13' if value=='favorite' else 'M20 66q-9 4-10 11 M99 67q9 5 10 11'
 limbs=f'<g class="call-face-limbs" stroke="var(--face-outline)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path class="call-face-hands" d="{hands}"/><path class="call-face-feet" d="M44 86v7m-4 2h8 M76 86v7m-4 2h8"/></g>' if arms else ''
 heart='<path class="call-face-heart" d="M101 25c-7-4-9-9-5-11 2-1 4 0 5 2 1-2 3-3 5-2 4 2 2 7-5 11Z" fill="var(--face-blush, #bd9986)"/>' if arms and value=='favorite' else ''
 eyes='M44 55q4-5 8 0 M68 55q4-5 8 0' if value=='favorite' else 'm42 54 12 1 m13 0 12-1 M49 57v2 M71 57v2' if value=='meh' else 'M49 55v3 M71 58v3'
 mouth='M55 69q6 7 12-1' if value=='favorite' else 'M55 72h11' if value=='meh' else 'M55 74q5-4 11-2'
 return f'<svg class="call-face call-face-{value}" viewBox="0 0 120 110" fill="none" aria-hidden="true">{limbs}<path class="call-face-body" d="{bodies[value]}" fill="var(--face-fill)" stroke="var(--face-fill)" stroke-width="2.4" stroke-linejoin="round"/>{heart}<g fill="var(--face-blush, #bd9986)" opacity="0.65"><ellipse cx="36" cy="67" rx="4.5" ry="2.6"/><ellipse cx="83" cy="67" rx="4.5" ry="2.6"/></g><g class="call-face-eyes" stroke="var(--face-ink)" stroke-width="2.8" stroke-linecap="round"><path d="{eyes}"/></g><path d="{mouth}" stroke="var(--face-ink)" stroke-width="3" stroke-linecap="round"/></svg>'
labels={'favorite':'Favorite','meh':'Meh','would_not_again':'Not again'}
def badge(v):return f'<span class="call-badge call-badge-{v}">{face(v)}<span>{labels[v]}</span></span>'
def slip(title='Lagavulin 16',typ='Whiskey',rank='03',example=False):
 return f'<aside class="opinion-slip"><div class="opinion-slip-top"><p class="overline">YOUR CALL{ " / EXAMPLE" if example else ""}</p><span>{rank}</span></div><h3>{title}</h3><p class="opinion-slip-type">{typ}</p><div class="opinion-slip-verdict">{face(arms=True)}<strong>Meh.</strong><span>It was a thing.</span></div><div class="call-choices" data-choice="meh">'+''.join(f'<button class="{ "active" if v=="meh" else ""}" aria-pressed="{str(v=="meh").lower()}"><span>{l}</span></button>' for v,l in labels.items())+('</div>' if example else '</div><div class="collection-tray-actions"><details class="collection-rank-disclosure"><summary>Rank</summary></details><button>Note</button><button>Revisit</button><button class="collection-open-details">Details →</button></div>')+'</aside>'
def rail(active='Archive'):
 return '<aside class="app-rail"><a class="brand">worth</a><button class="mobile-menu-toggle icon-button">☰</button><nav class="main-nav">'+''.join(f'<a class="{ "active" if x==active else ""}">{x}</a>' for x in ('Archive','Collections','Activity','Patterns','Search'))+'</nav><nav class="rail-collections"><p>Collections</p><a>Drinks <small>8</small></a><a>Movies <small>1</small></a><a>Places <small>1</small></a></nav><div class="rail-actions"><button class="button header-add">Add something +</button><a class="account-link"><span class="account-avatar">P</span><span>Preview archive<small>Account settings ↗</small></span></a></div></aside>'
def shell(content,active='Archive'):return '<div class="app-shell app-shell-dark">'+rail(active)+'<div class="app-content">'+content+'</div></div>'
def save(name,content): (root/f'{name}.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Worth — {name} reference</title>{head}<body>{content}</body></html>')
landing='<main class="cabinet-landing"><header class="cabinet-landing-top"><span class="product-wordmark">worth</span><a>Sign in →</a></header><section class="cabinet-landing-hero"><div><p class="overline">YOUR TASTE, ON RECORD</p><h1>For the good.<br>And the <em>meh.</em></h1></div><div class="cabinet-landing-intro"><p>Keep what you try.<br>Find what’s worth repeating.</p><a class="button button-accent">Start your archive <span>→</span></a></div></section><section class="cabinet-demo"><div class="cabinet-demo-index"><div class="demo-tabs"><button aria-pressed="true">Drinks</button><button>Movies</button><button>Places</button></div><div class="demo-heading"><div><h2>Drinks</h2><span>3 items · EXAMPLE</span></div></div><ol class="demo-index">'
for rank,title,typ,v in [('01','Dry Riesling','Wine','favorite'),('02','Cold brew','Coffee','meh'),('—','Highball','Cocktail','would_not_again')]:landing+=f'<li class="{ "selected" if v=="meh" else ""}"><button><span class="demo-rank">{rank}</span><span class="demo-item-name"><strong>{title}</strong><small>{typ}</small></span>{badge(v)}</button></li>'
landing+='</ol><form class="demo-capture"><input placeholder="What did you try?"><button class="button button-accent" disabled>Keep it <span>→</span></button></form><p class="demo-footnote">Just an example. Your actual opinions go in your archive.</p></div>'+slip('Cold brew','Coffee','02',True)+'</section><footer class="cabinet-landing-bottom"><strong>Meh is a complete sentence.</strong><span>Collections, rankings & a place to remember.</span></footer></main>'
# Keep the reference's DOM order equal to the live landing: introduction, opinion, index.
hero_start=landing.index('<section class="cabinet-landing-hero">')
demo_start=landing.index('<section class="cabinet-demo">')
hero=landing[hero_start:demo_start]
landing=landing[:hero_start]+landing[demo_start:]
card=slip('Cold brew','Coffee','02',True)
landing=landing.replace(card,'',1)
landing=landing.replace('<section class="cabinet-demo">','<section class="cabinet-demo">'+hero+card,1)
save('landing',landing)
home='<main class="cabinet-home page-width"><header class="cabinet-heading"><div><p class="overline">SATURDAY, OCTOBER 10</p><h1>The archive.</h1><p>Good finds. Mixed feelings.</p></div><div class="cabinet-wink">'+face()+'<span>Opinions may vary.<br>Yours, mostly.</span></div></header><section><header class="cabinet-section-head"><h2>Your collections</h2><a>View all →</a></header><ol class="cabinet-shelves">'
for i,name,count in [(1,'Drinks','8 items · 5 ranked'),(2,'Movies','1 item · 1 ranked'),(3,'Places','1 item · 1 ranked')]:home+=f'<li><a class="cabinet-folder"><div class="cabinet-folder-picture"><img src="../../../public/art/starter-covers/{name.lower()}-v1.webp" alt=""><span class="cabinet-folder-number">0{i}</span></div><div class="cabinet-folder-copy"><span><strong>{name}</strong><small>{count}</small></span><span>↗</span></div></a></li>'
home+='</ol></section><div class="cabinet-home-lower"><section class="cabinet-recent"><header class="cabinet-section-head"><h2>Recently filed</h2><a>View all →</a></header><ol class="activity-rail">'
for day,title,typ,v in [('OCT 09','Lagavulin 16','Drinks · Whiskey','meh'),('OCT 08','Perfect Days','Movies','favorite'),('OCT 07','The corner bakery','Places','favorite'),('OCT 06','Morning run','Running · 5 km',None)]:home+=f'<li><time>{day}</time><a><strong>{title}</strong><span>{typ}</span></a>{badge(v) if v else ""}</li>'
home+='</ol></section><aside><a class="cabinet-pick"><p class="overline">TOP OF THE LIST</p><div class="cabinet-pick-rank"><span>01</span><small>Within Drinks ↗</small></div><h3>Ardbeg Uigeadail</h3><p>Whiskey · Ranked by you</p></a><a class="cabinet-last-done"><span>Last done <strong>Morning run</strong></span><span>4 days ago →</span></a></aside></div></main>'
save('archive',shell(home))
collection='<main class="light-page list-page page-width collection-list-page"><a class="back-link">← Collections</a><section class="list-page-head"><div><p class="overline">YOUR COLLECTION</p><h1>Drinks</h1><p class="list-record-count">8 items · 5 ranked</p></div><div class="list-head-actions"><a class="button button-outline">Show list</a><button class="button button-outline">Share</button><button class="icon-button">⚙</button></div></section><section class="collection-workspace"><div class="cabinet-collection-body"><div class="cabinet-collection-main"><form class="collection-capture"><label><input placeholder="What did you try?"></label><button class="collection-capture-submit" disabled>Keep it →</button><div class="collection-capture-note"><button>Add several</button><p>Rank later. No rush.</p></div></form><div class="collection-index-layout"><div class="cabinet-index-toolbar"><nav class="collection-browse"><button class="active">All</button><button>Favorites</button><button>Revisited</button><button>Not opened lately</button></nav><div class="collection-utilities"><button class="collection-search-toggle"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg> Search</button><button class="collection-search-toggle">Filter</button></div></div><ol class="collection-index-rows">'
for i,title,typ,v in [(1,'Ardbeg Uigeadail','Whiskey','favorite'),(2,'Barolo','Wine','favorite'),(3,'Lagavulin 16','Whiskey','meh'),(4,'Negroni','Cocktail',None),(5,'Chablis','Wine','would_not_again')]:collection+=f'<li class="{ "selected" if i==3 else ""}"><div class="collection-index-row"><span class="collection-row-rank">0{i}</span><button><strong>{title}</strong><span>{typ}</span></button>{badge(v) if v else ""}</div>{slip() if i==3 else ""}</li>'
# Mobile uses the same slip inside the selected row.
collection=collection.replace('<aside class="opinion-slip"><div class="opinion-slip-top">','<aside class="collection-action-tray opinion-slip"><div class="opinion-slip-top">')
collection+='</ol><section class="collection-unranked"><p>Unranked · 3</p><ol class="collection-index-rows"><li><div class="collection-index-row"><span class="collection-row-rank">—</span><button><strong>Cold brew</strong><span>Coffee</span></button>'+badge('meh')+'</div></li></ol></section></div></div>'+slip()+'</div></section></main>'
save('collection',shell(collection,'Collections'))
